INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('cpo-morning-checkin', 'cpo-psychologist', 'Morning Emotional Check-in', 'Scan yesterday emotional state, check 5D scores, assess readiness for today', 'cron', '0 7 * * *', 'custom_prompt', '{"prompt":"Execute Morning Emotional Check-in. Step 1: Call lifeos_subjective_journal with period=past_day to review yesterday emotional state. Step 2: Score 5D dimensions (Depression, Anxiety, Stress, Energy, Satisfaction) from journal entries. Step 3: Call lifeos_activity_log with period=past_day to check energy and mood_delta for correlation. Step 4: Assess readiness for today based on emotional trajectory. Produce: 1) Brief emotional snapshot — dominant mood and 5D scores, 2) Energy-mood correlation insights, 3) Readiness assessment for today, 4) Any intervention needed. If stable: reply HEARTBEAT_OK. If concerning trends: produce brief with recommendations.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cpo-weekly-review', 'cpo-psychologist', 'Weekly Inner Review', 'Weekly emotional pattern analysis with cross-domain correlation', 'cron', '0 19 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Inner Review. Step 1: Call lifeos_subjective_journal with period=past_week to gather all emotional data. Step 2: Call lifeos_journal_synthesis with period=past_week for synthesized insights. Step 3: Call lifeos_activity_log with period=past_week to correlate emotional trends with activity energy. Step 4: Identify burnout signals — sustained low energy, increasing stress, declining mood. Step 5: Cross-correlate emotional patterns with productivity and health domains. Produce: 1) Weekly emotional trend report — mood trajectory, stress patterns, 2) Burnout risk assessment, 3) Cross-domain correlation insights, 4) Growth opportunities. Save synthesis to subjective_journal. SYSTEMIC FLAG CHECK: If burnout signals detected or emotional decline sustained 7+ days → send message.send to ceo-strategic with psychological pattern flag. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cpo-monthly-synthesis', 'cpo-psychologist', 'Monthly Inner-Life Synthesis', 'Monthly emotional trend analysis and growth opportunity identification', 'cron', '0 17 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Inner-Life Synthesis. Step 1: Call lifeos_subjective_journal with period=past_month for comprehensive emotional data. Step 2: Call lifeos_journal_synthesis with period=past_month for monthly synthesis. Step 3: Call lifeos_temporal_analysis with period=past_month for temporal emotional patterns. Step 4: Analyze recurring themes across the month. Step 5: Compare month-over-month trends for each 5D dimension. Produce: 1) Monthly emotional trend analysis — patterns, triggers, improvements, 2) Month-over-month comparison for all 5D dimensions, 3) Recurring theme identification, 4) Growth opportunities and interventions, 5) Overall psychological health score. Save comprehensive synthesis to subjective_journal. SYSTEMIC FLAG CHECK: If systemic emotional patterns detected (recurring negative themes, declining trajectory month-over-month) → send message.send to ceo-strategic with systemic psychological pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
